// Command wiregen generates package wire from the llumiverse JSON Schema document.
//
// The document (schema/llumiverse.schema.json) is generated by the TypeScript llumiverse from its Zod
// schemas, so both clients describe the same shapes. wiregen wraps its $defs as OpenAPI components,
// rewrites the few JSON Schema 2020-12 keywords oapi-codegen (an OpenAPI 3.0 generator) does not read,
// and runs the oapi-codegen version pinned in this module's go.mod.
//
// Run it through `go generate ./wire` from the repository root.
package main

import (
	"encoding/json"
	"flag"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
)

func main() {
	in := flag.String("in", "../schema/llumiverse.schema.json", "llumiverse JSON Schema document")
	config := flag.String("config", "../wire/oapi-codegen.yaml", "oapi-codegen configuration")
	flag.Parse()
	if err := run(*in, *config); err != nil {
		fmt.Fprintln(os.Stderr, "wiregen:", err)
		os.Exit(1)
	}
}

func run(in, config string) error {
	raw, err := os.ReadFile(in)
	if err != nil {
		return err
	}
	spec, err := toOpenAPI(raw)
	if err != nil {
		return err
	}
	tmp, err := os.MkdirTemp("", "wiregen")
	if err != nil {
		return err
	}
	defer os.RemoveAll(tmp)
	specPath := filepath.Join(tmp, "llumiverse.openapi.json")
	if err := os.WriteFile(specPath, spec, 0o600); err != nil {
		return err
	}
	cmd := exec.Command("go", "tool", "oapi-codegen", "-config", config, specPath)
	cmd.Stdout, cmd.Stderr = os.Stdout, os.Stderr
	return cmd.Run()
}

// goTypes replaces the generated struct of a definition with a Go type.
//
// JSONSchema is a caller's schema, open on purpose: it carries keywords it does not declare (enum,
// oneOf, minimum, $ref, ...). A struct keeps only its declared fields and would drop the rest on the next
// encode, so it is a map, the form the drivers already rewrite schemas in.
var goTypes = map[string]string{
	"JSONSchema": "map[string]any",
}

// toOpenAPI wraps the document's $defs as the components of an otherwise empty OpenAPI 3.0 document.
func toOpenAPI(raw []byte) ([]byte, error) {
	var doc struct {
		Defs map[string]any `json:"$defs"`
	}
	if err := json.Unmarshal(raw, &doc); err != nil {
		return nil, fmt.Errorf("parse schema document: %w", err)
	}
	if len(doc.Defs) == 0 {
		return nil, fmt.Errorf("schema document has no $defs")
	}
	for name, def := range doc.Defs {
		doc.Defs[name] = downgrade(def)
	}
	for name, goType := range goTypes {
		def, ok := doc.Defs[name].(map[string]any)
		if !ok {
			return nil, fmt.Errorf("schema document has no %s definition", name)
		}
		def["x-go-type"] = goType
		def["x-go-type-skip-optional-pointer"] = true
	}
	return json.MarshalIndent(map[string]any{
		"openapi": "3.0.3",
		"info":    map[string]any{"title": "llumiverse", "version": "0"},
		"paths":   map[string]any{},
		"components": map[string]any{
			"schemas": doc.Defs,
		},
	}, "", "  ")
}

// downgrade rewrites JSON Schema 2020-12 keywords into their OpenAPI 3.0 spelling. Each rewrite
// keeps the meaning; only the spelling changes.
func downgrade(node any) any {
	switch n := node.(type) {
	case []any:
		for i, child := range n {
			n[i] = downgrade(child)
		}
		return n
	case map[string]any:
		if ref, ok := n["$ref"].(string); ok {
			n["$ref"] = strings.Replace(ref, "#/$defs/", "#/components/schemas/", 1)
		}
		if mapping, ok := n["discriminator"].(map[string]any); ok {
			if refs, ok := mapping["mapping"].(map[string]any); ok {
				for key, ref := range refs {
					if s, ok := ref.(string); ok {
						refs[key] = strings.Replace(s, "#/$defs/", "#/components/schemas/", 1)
					}
				}
			}
		}
		// const: one-value enum.
		if value, ok := n["const"]; ok {
			n["enum"] = []any{value}
			delete(n, "const")
		}
		// Numeric exclusive bounds: a bound plus a boolean flag.
		for _, bound := range [][2]string{{"exclusiveMinimum", "minimum"}, {"exclusiveMaximum", "maximum"}} {
			if value, ok := n[bound[0]].(float64); ok {
				n[bound[1]] = value
				n[bound[0]] = true
			}
		}
		// anyOf [X, {type: null}]: X marked nullable.
		if branches, ok := n["anyOf"].([]any); ok {
			kept := make([]any, 0, len(branches))
			nullable := false
			for _, branch := range branches {
				if b, ok := branch.(map[string]any); ok && b["type"] == "null" && len(b) == 1 {
					nullable = true
					continue
				}
				kept = append(kept, branch)
			}
			if nullable {
				n["nullable"] = true
				if len(kept) == 1 {
					delete(n, "anyOf")
					// A $ref cannot carry siblings in 3.0; allOf around it can.
					n["allOf"] = kept
				} else {
					n["anyOf"] = kept
				}
			}
		}
		// A JSON number is a double; oapi-codegen otherwise picks float32, which cannot hold a
		// token count or a cost exactly.
		if n["type"] == "number" {
			if _, ok := n["format"]; !ok {
				n["format"] = "double"
			}
		}
		delete(n, "propertyNames")
		for key, child := range n {
			n[key] = downgrade(child)
		}
		return n
	default:
		return node
	}
}
